import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Trash2, Edit, Check, X } from 'lucide-react';
import { useSelector, useDispatch } from 'react-redux';
import { fetchComments, selectComments } from '../../features/comments/commentsSlice';
import { selectProposals } from '../../features/proposals/proposalsSlice';

const CommentsPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const assignmentId = Number(id);
  const dispatch = useDispatch();
  const comments = useSelector(selectComments);
  const assignments = useSelector(selectProposals);
  const assignment = assignments.find((a) => a.id === assignmentId);

  useEffect(() => {
    if (id) dispatch(fetchComments(id));
  }, [dispatch, id]);
  const currentUser = useSelector((s) => s.auth.user);

  const myComments = comments.filter((c) => Number(c.assignmentId) === assignmentId);


  return (
    <div className="min-h-screen bg-[#F3F4F6] p-6">

      {/* Header */}
      <div className="flex items-center gap-4 mb-6">
        <button
          onClick={() => navigate(-1)}
          className="p-2 hover:bg-gray-200 rounded-full transition-colors"
          aria-label="Go back"
        >
          <ArrowLeft size={20} className="text-gray-800" />
        </button>
        <div>
          <h1 className="text-xl font-bold text-gray-900">
            Comments — {assignment?.applicationCode || `Assignment ${assignmentId}`}
          </h1>
          <p className="text-sm text-gray-500 mt-0.5">{assignment?.title}</p>
        </div>
      </div>

      {/* Comments list */}
      <div className="space-y-4 max-w-3xl mx-auto">
        {myComments.length === 0 ? (
          <div className="bg-white rounded-2xl p-12 text-center">
            <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-gray-400">
                <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
              </svg>
            </div>
            <p className="font-bold text-gray-500">No comments yet</p>
            <p className="text-gray-400 text-sm mt-1">Comments you add during review will appear here.</p>
          </div>
        ) : (
          myComments.map((c) => (
            <div key={c.id} className="bg-white rounded-2xl p-5 shadow-sm">
              <>
                <p className="text-gray-800 text-sm whitespace-pre-wrap leading-relaxed">{c.text}</p>
                <div className="flex items-center justify-between mt-3">
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-gray-400">
                      {new Date(c.date).toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                      {c.editedAt && ' · edited'}
                    </span>
                    {c.section && (
                      <span className="bg-blue-50 text-[#003B95] text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wider border border-blue-100">
                        {c.section}
                      </span>
                    )}
                  </div>
                </div>
              </>
            </div>
          ))
        )}
      </div>

      {/* Comment count footer */}
      {myComments.length > 0 && (
        <p className="text-center text-gray-400 text-sm font-medium mt-6">{myComments.length} comment{myComments.length !== 1 ? 's' : ''}</p>
      )}
    </div>
  );
};

export default CommentsPage;

import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { loginUser, registerUser } from './authSlice';

const ROLE_SETTINGS = {
  reviewer: { title: 'Reviewer Login', color: '#003B95' },
  researcher: { title: 'Researcher Login', color: '#003B95' },
  admin: { title: 'Administrator Login', color: '#003B95' },
};

const ADMIN_EMAILS = ['admin@babcock.edu.ng', 'buhrec@babcock.edu.ng'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MIN_PASSWORD_LEN = 6;

// ── Researcher Sign-Up Form ───────────────────────────────────────────────────
const ResearcherSignUp = ({ onBack }) => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: '', email: '', dob: '', institution: '', occupation: '', password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!EMAIL_RE.test(form.email)) {
      alert('Please enter a valid email address');
      return;
    }
    if (form.password.length < MIN_PASSWORD_LEN) {
      alert(`Password must be at least ${MIN_PASSWORD_LEN} characters`);
      return;
    }
    setIsLoading(true);
    dispatch(registerUser({ ...form, role: 'researcher' }))
      .unwrap()
      .then(() => {
        setIsLoading(false);
        navigate('/dashboard');
      })
      .catch(() => {
        setIsLoading(false);
      });
  };

  return (
    <div className="min-h-screen bg-[#E5E7EB] flex items-center justify-center p-4">
      <div className="bg-white p-6 sm:p-10 rounded-2xl shadow-sm w-full max-w-md">
        <h1 className="text-2xl sm:text-3xl font-bold text-gray-900 mb-1">Researcher Sign Up</h1>
        <p className="text-gray-600 mb-6 text-sm">Create a researcher account</p>

        <form className="space-y-4" onSubmit={handleSubmit}>
          {/* Name */}
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-1">Name</label>
            <input
              name="name" value={form.name} onChange={handleChange} required
              className="w-full bg-[#F3F4F6] rounded-lg px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Email */}
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-1">Email</label>
            <input
              type="email" name="email" value={form.email} onChange={handleChange} required
              className="w-full bg-[#F3F4F6] rounded-lg px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Date of Birth */}
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-1">Date of Birth</label>
            <input
              type="date" name="dob" value={form.dob} onChange={handleChange} required
              className="w-full bg-[#F3F4F6] rounded-lg px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 text-gray-700"
            />
          </div>

          {/* Institution */}
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-1">Institution</label>
            <input
              name="institution" value={form.institution} onChange={handleChange} required
              className="w-full bg-[#F3F4F6] rounded-lg px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Occupation */}
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-1">Occupation</label>
            <input
              name="occupation" value={form.occupation} onChange={handleChange} required
              className="w-full bg-[#F3F4F6] rounded-lg px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-1">Password</label>
            <input
              type={showPassword ? 'text' : 'password'}
              name="password" value={form.password} onChange={handleChange} required
              className="w-full bg-[#F3F4F6] rounded-lg px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Show password */}
          <div className="flex items-center space-x-2">
            <input
              type="checkbox" id="su-show-pass" checked={showPassword}
              onChange={() => setShowPassword((s) => !s)}
              className="w-4 h-4" style={{ accentColor: '#003B95' }}
            />
            <label htmlFor="su-show-pass" className="text-sm text-gray-600 cursor-pointer">Show Password</label>
          </div>

          {/* Submit */}
          <div className="flex justify-center pt-2">
            <button
              type="submit" disabled={isLoading}
              className="w-full sm:w-1/2 bg-[#003B95] hover:bg-blue-900 text-white py-3 rounded-full font-semibold transition-all active:scale-95 disabled:opacity-50"
            >
              {isLoading ? 'Creating account...' : 'Sign Up'}
            </button>
          </div>

          {/* Back to login */}
          <p className="text-center text-sm text-gray-500">
            Already have an account?{' '}
            <button type="button" onClick={onBack} className="text-[#003B95] font-semibold hover:underline">
              Log in
            </button>
          </p>
        </form>
      </div>
    </div>
  );
};

// ── Unified Login Page ────────────────────────────────────────────────────────
const UnifiedLoginPage = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { role } = useParams();
  const currentRole = role && ROLE_SETTINGS[role] ? role : 'reviewer';


  const [showSignUp, setShowSignUp] = useState(false);
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // If researcher wants to sign up, show sign-up form
  if (currentRole === 'researcher' && showSignUp) {
    return <ResearcherSignUp onBack={() => setShowSignUp(false)} />;
  }

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (error) setError('');
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!formData.email || !formData.password) {
      setError('Please fill in all fields');
      return;
    }
    if (!EMAIL_RE.test(formData.email)) {
      setError('Please enter a valid email address');
      return;
    }
    if (formData.password.length < MIN_PASSWORD_LEN) {
      setError(`Password must be at least ${MIN_PASSWORD_LEN} characters`);
      return;
    }

    setIsLoading(true);
    setError('');
    try {
      await dispatch(loginUser({ email: formData.email, password: formData.password, role: currentRole })).unwrap();
      navigate('/dashboard');
    } catch (err) {
      setError(err || 'Login failed. Please check your credentials.');
    } finally {
      setIsLoading(false);
    }
  };

  const settings = ROLE_SETTINGS[currentRole];

  return (
    <div className="min-h-screen bg-[#E5E7EB] flex items-center justify-center p-4">
      <div className="bg-white p-6 sm:p-10 rounded-2xl shadow-sm w-full max-w-md">
        <h1 className="text-2xl sm:text-3xl font-bold text-gray-900 mb-1">{settings.title}</h1>
        <p className="text-gray-600 mb-8 text-sm">Sign In to your account</p>

        {error && (
          <div className="mb-4 p-3 bg-red-100 text-red-600 text-xs rounded-lg border border-red-200">
            {error}
          </div>
        )}

        <form className="space-y-4 sm:space-y-6" onSubmit={handleLogin}>
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-2">Email</label>
            <input
              type="email" name="email" value={formData.email} onChange={handleChange}
              className="w-full bg-[#F3F4F6] border-none rounded-lg p-3 sm:p-4 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-900 mb-2">Password</label>
            <input
              type={showPassword ? 'text' : 'password'} name="password"
              value={formData.password} onChange={handleChange}
              className="w-full bg-[#F3F4F6] border-none rounded-lg p-3 sm:p-4 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div className="flex items-center space-x-3">
            <input
              type="checkbox" id="show-pass" checked={showPassword}
              onChange={() => setShowPassword(!showPassword)}
              className="w-4 h-4" style={{ accentColor: settings.color }}
            />
            <label htmlFor="show-pass" className="text-sm text-gray-600 cursor-pointer">Show Password</label>
          </div>
          <div className="flex justify-center pt-2">
            <button
              type="submit" disabled={isLoading}
              className="text-white px-12 py-3 rounded-full font-semibold w-full sm:w-1/2 transition-all active:scale-95 disabled:opacity-50"
              style={{ backgroundColor: settings.color }}
            >
              {isLoading ? 'Logging in...' : 'Log in'}
            </button>
          </div>
        </form>

        {/* Sign-up link — only for researcher */}
        {currentRole === 'researcher' && (
          <p className="text-center text-sm text-gray-500 mt-6">
            Don't have an account?{' '}
            <button
              onClick={() => setShowSignUp(true)}
              className="text-[#003B95] font-semibold hover:underline"
            >
              Create one
            </button>
          </p>
        )}
      </div>
    </div>
  );
};

export default UnifiedLoginPage;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { X, MoreVertical } from 'lucide-react';
import { removeReviewer } from '../../features/reviewers/reviewersSlice';

const FILTER_OPTIONS = ['Title', 'Years in Practice', 'Specialization', 'Institution'];

// ── Reviewer Profile Modal ───────────────────────────────────────────────────
const ReviewerModal = ({ reviewer, onClose }) => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showDeactivateConfirm, setShowDeactivateConfirm] = useState(false);

  const initials = reviewer.name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .slice(0, 2);

  const statCards = [
    { label: 'Accepted Assignments', value: reviewer.stats.accepted },
    { label: 'Completed Assignments', value: reviewer.stats.completed },
    { label: 'Incomplete Assignments', value: reviewer.stats.incomplete },
    { label: 'Pending Feedback', value: reviewer.stats.pendingFeedback },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/40 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Modal Card */}
      <div className="relative bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden">
        {/* Close button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 z-10 p-1.5 hover:bg-gray-100 rounded-full transition-colors"
        >
          <X size={20} className="text-gray-500" />
        </button>

        <div className="p-6 sm:p-8 max-h-[90vh] overflow-y-auto no-scrollbar">
          {/* ── Profile Header ─────────────────────────────── */}
          <div className="flex flex-col sm:flex-row items-center sm:items-start gap-5 mb-8 text-center sm:text-left">
            {/* Avatar */}
            <div className="w-20 h-20 rounded-full bg-[#003B95]/20 flex items-center justify-center text-[#003B95] font-bold text-2xl flex-shrink-0 border-4 border-gray-100 shadow overflow-hidden">
              {reviewer.avatar ? (
                <img
                  src={reviewer.avatar}
                  alt={reviewer.name}
                  className="w-full h-full object-cover"
                />
              ) : (
                initials
              )}
            </div>

            {/* Name + specialization */}
            <div className="flex-1 min-w-0">
              <h2 className="text-xl font-bold text-gray-900 leading-tight">
                {reviewer.name}
              </h2>
              <p className="text-gray-500 text-sm mt-1">{reviewer.specialization}</p>
            </div>

            {/* 3-dot menu */}
            <div className="relative flex-shrink-0 self-end sm:self-start">
              <button
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              >
                <MoreVertical size={20} className="text-gray-600" />
              </button>
              {isMenuOpen && (
                <>
                  <div
                    className="fixed inset-0 z-40"
                    onClick={() => setIsMenuOpen(false)}
                  />
                  <div className="absolute right-0 mt-2 w-52 bg-white rounded-xl shadow-xl border border-gray-100 py-1.5 z-50">
                    <button
                      onClick={() => {
                        setIsMenuOpen(false);
                        setShowDeactivateConfirm(true);
                      }}
                      className="w-full text-left px-4 py-3 text-sm font-semibold text-red-600 hover:bg-red-50 transition-colors"
                    >
                      Remove Reviewer
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>

          {/* ── Info Grid ──────────────────────────────────── */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-8 bg-gray-50 p-6 rounded-2xl border border-gray-100">
            <div>
              <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-1.5">Title</p>
              <p className="font-bold text-gray-900 text-sm">{reviewer.title}</p>
            </div>
            <div>
              <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-1.5">Speciality</p>
              <p className="font-bold text-gray-900 text-sm leading-tight">
                {reviewer.specialization}
              </p>
            </div>
            <div>
              <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mb-1.5">Institution</p>
              <p className="font-bold text-gray-900 text-sm">{reviewer.institution}</p>
            </div>
          </div>

          {/* ── Statistics ────────────────────────────────── */}
          <div className="mb-8">
            <h3 className="text-base font-black text-gray-900 uppercase tracking-widest mb-4">Statistics</h3>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {statCards.map((card) => (
                <div
                  key={card.label}
                  className="bg-[#F3F4F6] rounded-2xl p-4 flex flex-col justify-center items-center text-center"
                >
                  <p className="text-[8px] font-black text-gray-500 uppercase tracking-wide leading-tight mb-2">
                    {card.label}
                  </p>
                  <p className="text-2xl sm:text-3xl font-black text-gray-900">{card.value}</p>
                </div>
              ))}
            </div>
          </div>

          {/* ── View Assignments Button ───────────────────── */}
          <div className="flex justify-center pt-2">
            <button
              onClick={() => {
                onClose();
                navigate(`/dashboard/reviewers/${reviewer.id}/assignments`);
              }}
              className="w-full sm:w-auto bg-[#003B95] text-white px-12 py-3.5 rounded-full font-black text-xs uppercase tracking-[0.2em] hover:bg-blue-900 transition-all shadow-lg active:scale-95"
            >
              View Assignments
            </button>
          </div>
        </div>
      </div>

      {/* ── Deactivate Confirm Modal ──────────────────────── */}
      {showDeactivateConfirm && (
        <div className="fixed inset-0 z-60 flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
            onClick={() => setShowDeactivateConfirm(false)}
          />
          <div className="relative bg-white rounded-2xl p-8 w-full max-w-sm shadow-2xl text-center">
            <h2 className="text-xl font-bold text-gray-900 mb-2">
              Remove Reviewer?
            </h2>
            <p className="text-gray-400 text-sm mb-8">
              This will permanently remove {reviewer.name} from the system. They will no longer be able to access the review portal or be assigned new proposals.
            </p>
            <div className="flex space-x-3">
              <button
                onClick={() => setShowDeactivateConfirm(false)}
                className="flex-1 bg-gray-200 text-gray-800 py-3 rounded-full font-bold hover:bg-gray-300 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  dispatch(removeReviewer(Number(reviewer.id)));
                  setShowDeactivateConfirm(false);
                  onClose();
                }}
                className="flex-1 text-white py-3 rounded-full font-bold transition-all bg-[#C10000] hover:bg-red-700"
              >
                Remove
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper for initials
const initialsForReviewer = (name) => name?.split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase() || '??';

// ── Main Reviewers Page ──────────────────────────────────────────────────────
const Reviewers = () => {
  const navigate = useNavigate();
  const reviewers = useSelector(state => state.reviewers.items);
  const [activeFilter, setActiveFilter] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedReviewer, setSelectedReviewer] = useState(null);

  const filteredReviewers = React.useMemo(() => {
    let result = reviewers.filter(
      (r) =>
        r.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        r.specialization.toLowerCase().includes(searchQuery.toLowerCase())
    );

    // Sort by the active filter category
    if (activeFilter === 'Title') {
      result = [...result].sort((a, b) => (a.title || '').localeCompare(b.title || ''));
    } else if (activeFilter === 'Years in Practice') {
      result = [...result].sort((a, b) => (b.yearsOfExperience || 0) - (a.yearsOfExperience || 0));
    } else if (activeFilter === 'Specialization') {
      result = [...result].sort((a, b) => (a.specialization || '').localeCompare(b.specialization || ''));
    } else if (activeFilter === 'Institution') {
      result = [...result].sort((a, b) => (a.institution || '').localeCompare(b.institution || ''));
    }

    return result;
  }, [reviewers, searchQuery, activeFilter]);

  return (
    <div className="bg-white min-h-screen p-4 sm:p-6 lg:p-8">
      <header className="mb-8 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Registered Reviewers</h1>
          <p className="text-gray-500 text-sm font-medium">Here are all registered reviewers!</p>
        </div>
        <button
          onClick={() => navigate('/dashboard/reviewers/add')}
          className="bg-[#003B95] text-white px-6 py-2.5 rounded-full font-bold hover:bg-blue-900 transition-colors text-sm"
        >
          Add Reviewer
        </button>
      </header>

      {/* Filter Tabs - Scrollable on mobile */}
      <div className="flex overflow-x-auto pb-4 sm:pb-0 no-scrollbar space-x-4 mb-8">
        {FILTER_OPTIONS.map((option) => (
          <button
            key={option}
            onClick={() => setActiveFilter(activeFilter === option ? null : option)}
            className={`px-5 py-2 rounded-full text-sm font-semibold transition-all shrink-0 ${activeFilter === option
              ? 'bg-[#003B95] text-white'
              : 'bg-transparent text-gray-600 hover:bg-gray-100'
              }`}
          >
            {option}
          </button>
        ))}
      </div>

      {/* Reviewers List */}
      <div className="space-y-3">
        {filteredReviewers.map((reviewer) => (
          <div
            key={reviewer.id}
            onClick={() => setSelectedReviewer(reviewer)}
            className="bg-[#F3F4F6] p-5 rounded-2xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 hover:shadow-md hover:bg-[#E9EEF8] transition-all cursor-pointer"
          >
            <div className="flex items-center space-x-4 w-full sm:w-auto">
              {/* Avatar */}
              <div className="w-12 h-12 rounded-full bg-gray-300 overflow-hidden border-2 border-gray-200 flex-shrink-0">
                {reviewer.avatar ? (
                  <img src={reviewer.avatar} alt={reviewer.name} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full bg-[#003B95]/20 flex items-center justify-center text-[#003B95] font-bold text-lg">
                    {initialsForReviewer(reviewer.name)}
                  </div>
                )}
              </div>
              <div className="min-w-0 flex-1">
                <p className="font-bold text-gray-900 truncate">{reviewer.name}</p>
                <p className="text-gray-500 text-sm truncate">{reviewer.specialization}</p>
              </div>
            </div>
            <div className="text-[#003B95] font-semibold text-sm self-end sm:self-auto shrink-0">
              {reviewer.ongoingAssignments} ongoing assignments
            </div>
          </div>
        ))}
      </div>

      {filteredReviewers.length === 0 && (
        <div className="text-center py-20">
          <p className="text-gray-400 font-bold text-lg">No reviewers found</p>
        </div>
      )}

      {/* Reviewer Profile Modal */}
      {selectedReviewer && (
        <ReviewerModal
          reviewer={selectedReviewer}
          onClose={() => setSelectedReviewer(null)}
        />
      )}

    </div>
  );
};

export default Reviewers;
